#!/usr/bin/env bash
# Work git identity, applied only inside ~/dev/harperfast (see the includeIf
# in the core .gitconfig).

WORK_EMAIL="${WORK_EMAIL:-ethan@harperdb.io}"

write_file "$STATE_DIR/gitconfig.work" <<WORKCFG
# Generated by \`dotfiles install\`. Applied only to repos under ~/dev/harperfast/.
[user]
	email = $WORK_EMAIL
WORKCFG

[[ -d "$HOME/dev/harperfast" ]] || log_warn "~/dev/harperfast does not exist yet; the work identity will apply once it does"
